// エラー実行とトリガー起動失敗の両方に対応してSlack向けメッセージを作る
const d = $input.first().json;
const wf = d.workflow ?? {};
const exec = d.execution ?? {};
const trg = d.trigger ?? {};

const isTriggerError = !exec.id && trg.error != null;
const err = (isTriggerError ? trg.error : exec.error) ?? {};

const now = new Intl.DateTimeFormat('ja-JP', {
  timeZone: 'Asia/Tokyo',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
}).format(new Date());

const lines = [
  '\u{1F6A8} ワークフローがエラーで停止しました',
  '',
  `ワークフロー: ${wf.name ?? '(不明)'}`,
  `発生時刻: ${now}`,
];

const failedNode = exec.lastNodeExecuted ?? err.node?.name;
if (failedNode) lines.push(`失敗ノード: ${failedNode}`);

lines.push('', 'エラー内容:');
lines.push(String(err.message ?? '(詳細不明)').slice(0, 500));

if (exec.url) lines.push('', `実行ログ: ${exec.url}`);
if (isTriggerError) {
  lines.push('', '\u26A0\uFE0F トリガーの起動に失敗しています。ワークフローが動いていない可能性があります。');
}

return [{ json: { text: lines.join('\n') } }];
